style.css:
@-moz-document url("https://www.roblox.com/home") {
body {
    background-image: url("https://your-image-link-here.com/image.jpg");
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
    background-position: center center;
  }

  /* Optional: Make background visible by hiding default background layers */
  .content, .container-main, .rbx-home-page {
    background: transparent !important;
  }
}
